import { SphereGeometry, CylinderGeometry, CircleGeometry, BoxGeometry, TorusGeometry, Group, Mesh, MeshStandardMaterial } from './src/mini3d.js';
import assert from 'node:assert/strict';
for (const geometry of [new SphereGeometry(1,40,28),new CylinderGeometry(.5,1,2,64),new CircleGeometry(1,48),new BoxGeometry(1,2,3),new TorusGeometry(.4,.06,12,40)]) {
assert.equal(geometry.positions.length,geometry.normals.length);
assert.equal(geometry.indices.length%3,0);
assert.ok([...geometry.positions,...geometry.normals].every(Number.isFinite));
assert.ok(Math.max(...geometry.indices)<geometry.positions.length/3);
}
const group=new Group();const mesh=new Mesh(new SphereGeometry(),new MeshStandardMaterial({color:'#ffffff'}));group.add(mesh);assert.equal(mesh.parent,group);assert.deepEqual(mesh.material.color.rgb,[1,1,1]);console.log('PASS: all 3D mesh geometry, color conversion, and scene hierarchy checks');
EOF
NODE_USE_SYSTEM_CA=0 pnpm run check; NODE_USE_SYSTEM_CA=0 pnpm run build"

